This sample shows how to call GetPolicyCertificateAsync and parse the result.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
PolicyCertificates client = new AttestationClient(endpoint, credential).GetPolicyCertificatesClient(apiVersion: "2025-06-01");

Response response = await client.GetPolicyCertificateAsync(null);

JsonElement result = JsonDocument.Parse(response.ContentStream).RootElement;
Console.WriteLine(result.ToString());

